*** Add File: /private/var/folders/0q/2rdtymtx2yvgjq38pr1pm2lc0000gn/T/opencode-skill-state-one-shot/20260904T203726Z/skill-state/taskboard-cli/src/cli.ts
+type Status = "open" | "done";
+
+type Task = {
+  id: number;
+  title: string;
+  tags: string[];
+  status: Status;
+  createdAt: string;
+  due?: string;
+  completedAt?: string;
+};
+
+type Database = { tasks: Task[]; nextId: number };
+
+const databasePath = process.env.TASKBOARD_FILE || `${process.cwd()}/.taskboard.json`;
+
+function fail(message: string): never {
+  console.error(message);
+  process.exit(1);
+}
+
+function today(): string {
+  const date = new Date();
+  const offset = date.getTimezoneOffset() * 60_000;
+  return new Date(date.getTime() - offset).toISOString().slice(0, 10);
+}
+
+function validDate(value: string): boolean {
+  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
+  const date = new Date(`${value}T00:00:00Z`);
+  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value;
+}
+
+function readDatabase(): Database {
+  if (!Bun.file(databasePath).size) return { tasks: [], nextId: 1 };
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(Bun.file(databasePath).textSync());
+  } catch {
+    fail("Malformed taskboard database");
+  }
+  if (
+    !parsed || typeof parsed !== "object" || !Array.isArray((parsed as Database).tasks) ||
+    !Number.isInteger((parsed as Database).nextId) || (parsed as Database).nextId < 1
+  ) fail("Malformed taskboard database");
+  const db = parsed as Database;
+  for (const task of db.tasks) {
+    if (!task || !Number.isInteger(task.id) || typeof task.title !== "string" ||
+      !Array.isArray(task.tags) || (task.status !== "open" && task.status !== "done") ||
+      typeof task.createdAt !== "string" || (task.due !== undefined && !validDate(task.due))) {
+      fail("Malformed taskboard database");
+    }
+  }
+  return db;
+}
+
+function writeDatabase(db: Database): void {
+  const temporary = `${databasePath}.${process.pid}.${Date.now()}.tmp`;
+  try {
+    Bun.write(temporary, `${JSON.stringify(db, null, 2)}\n`);
+    Bun.write; // Ensure Bun is available before rename is attempted.
+    require("fs").renameSync(temporary, databasePath);
+  } catch (error) {
+    try { require("fs").unlinkSync(temporary); } catch { /* nothing to clean up */ }
+    fail(`Unable to write taskboard database: ${error instanceof Error ? error.message : String(error)}`);
+  }
+}
+
+function parseOptions(args: string[], allowed: string[]): Map<string, string> {
+  const options = new Map<string, string>();
+  for (let index = 0; index < args.length; index += 2) {
+    const flag = args[index];
+    const value = args[index + 1];
+    if (!flag?.startsWith("--") || !allowed.includes(flag) || value === undefined || options.has(flag)) {
+      fail("Invalid command options");
+    }
+    options.set(flag, value);
+  }
+  return options;
+}
+
+function taskId(value: string | undefined): number {
+  if (!value || !/^\d+$/.test(value) || Number(value) < 1) fail("Invalid task id");
+  return Number(value);
+}
+
+const [command, ...args] = process.argv.slice(2);
+let output: unknown;
+
+switch (command) {
+  case "add": {
+    const options = parseOptions(args, ["--title", "--tags", "--due"]);
+    const title = options.get("--title")?.trim();
+    if (!title) fail("A non-empty title is required");
+    const due = options.get("--due");
+    if (due && !validDate(due)) fail("Invalid due date");
+    const tags = [...new Set((options.get("--tags") || "").split(",").map(tag => tag.trim().toLowerCase()).filter(Boolean))];
+    const db = readDatabase();
+    const task: Task = { id: db.nextId++, title, tags, status: "open", createdAt: new Date().toISOString(), ...(due ? { due } : {}) };
+    db.tasks.push(task);
+    writeDatabase(db);
+    output = task;
+    break;
+  }
+  case "list": {
+    const options = parseOptions(args, ["--status", "--tag", "--overdue"]);
+    const status = options.get("--status");
+    const tag = options.get("--tag")?.trim().toLowerCase();
+    const overdue = options.get("--overdue");
+    if (status && status !== "open" && status !== "done") fail("Invalid status");
+    if (overdue && !validDate(overdue)) fail("Invalid overdue date");
+    output = readDatabase().tasks.filter(task =>
+      (!status || task.status === status) && (!tag || task.tags.includes(tag)) &&
+      (!overdue || (task.status === "open" && !!task.due && task.due < overdue)),
+    ).sort((a, b) => a.id - b.id);
+    break;
+  }
+  case "done": {
+    if (args.length !== 1) fail("Usage: done ID");
+    const db = readDatabase();
+    const task = db.tasks.find(item => item.id === taskId(args[0]));
+    if (!task) fail("Task not found");
+    if (task.status === "open") {
+      task.status = "done";
+      task.completedAt = new Date().toISOString();
+      writeDatabase(db);
+    }
+    output = task;
+    break;
+  }
+  case "delete": {
+    if (args.length !== 1) fail("Usage: delete ID");
+    const db = readDatabase();
+    const id = taskId(args[0]);
+    const index = db.tasks.findIndex(task => task.id === id);
+    if (index < 0) fail("Task not found");
+    const [deleted] = db.tasks.splice(index, 1);
+    writeDatabase(db);
+    output = deleted;
+    break;
+  }
+  case "stats": {
+    if (args.length) fail("Usage: stats");
+    const tasks = readDatabase().tasks;
+    output = { total: tasks.length, open: tasks.filter(task => task.status === "open").length, done: tasks.filter(task => task.status === "done").length, overdue: tasks.filter(task => task.status === "open" && task.due && task.due < today()).length };
+    break;
+  }
+  default:
+    fail("Unknown command");
+}
+
+console.log(JSON.stringify(output));
*** Add File: /private/var/folders/0q/2rdtymtx2yvgjq38pr1pm2lc0000gn/T/opencode-skill-state-one-shot/20260904T203726Z/skill-state/taskboard-cli/README.md
+# Taskboard CLI
+
+A dependency-free task manager for Bun. Data is stored in `.taskboard.json` in the current directory, or in the path specified by `TASKBOARD_FILE`.
+
+```sh
+bun run src/cli.ts add --title "Buy milk" --tags home,errands --due 2026-09-10
+bun run src/cli.ts list --status open --tag home
+bun run src/cli.ts done 1
+bun run src/cli.ts stats
+bun run src/cli.ts delete 1
+```
+
+Each command prints one JSON value to standard output. Invalid commands, flags, dates, and missing tasks fail with a diagnostic on standard error.
+
+Run the self-tests with:
+
+```sh
+bun test
+```
*** Add File: /private/var/folders/0q/2rdtymtx2yvgjq38pr1pm2lc0000gn/T/opencode-skill-state-one-shot/20260904T203726Z/skill-state/taskboard-cli/test/cli.test.ts
+import { afterEach, expect, test } from "bun:test";
+import { mkdtempSync, rmSync } from "fs";
+import { tmpdir } from "os";
+import { join } from "path";
+
+const directory = mkdtempSync(join(tmpdir(), "taskboard-test-"));
+const database = join(directory, "tasks.json");
+const cli = join(import.meta.dir, "..", "src", "cli.ts");
+
+function run(...args: string[]) {
+  return Bun.spawnSync(["bun", "run", cli, ...args], { env: { ...process.env, TASKBOARD_FILE: database }, stdout: "pipe", stderr: "pipe" });
+}
+
+afterEach(() => rmSync(database, { force: true }));
+
+test("persists, filters, completes, and reports task statistics", () => {
+  let result = run("add", "--title", " First task ", "--tags", "Work,work, urgent ", "--due", "2020-01-01");
+  expect(result.exitCode).toBe(0);
+  expect(JSON.parse(result.stdout.toString())).toMatchObject({ id: 1, title: "First task", tags: ["work", "urgent"], status: "open", due: "2020-01-01" });
+  result = run("add", "--title", "Second");
+  expect(JSON.parse(result.stdout.toString())).toMatchObject({ id: 2, status: "open" });
+  result = run("list", "--tag", "WORK", "--overdue", "2021-01-01");
+  expect(JSON.parse(result.stdout.toString())).toHaveLength(1);
+  result = run("done", "1");
+  expect(JSON.parse(result.stdout.toString())).toMatchObject({ status: "done" });
+  result = run("done", "1");
+  expect(result.exitCode).toBe(0);
+  result = run("stats");
+  expect(JSON.parse(result.stdout.toString())).toEqual({ total: 2, open: 1, done: 1, overdue: 0 });
+});
+
+test("rejects invalid input without creating data", () => {
+  const result = run("add", "--title", "", "--due", "2024-02-30");
+  expect(result.exitCode).not.toBe(0);
+  expect(result.stdout.toString()).toBe("");
+  expect(Bun.file(database).size).toBe(0);
+});
*** End Patch

